import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface PlatformConfig {
  max_resumes_per_job: number;
  max_file_size_mb: number;
  resume_retention_days: number;
  payg_per_resume_cost: number;
  topup_min_amount: number;
  topup_dodo_product_id: string | null;
}

const DEFAULTS: PlatformConfig = {
  max_resumes_per_job: 10,
  max_file_size_mb: 5,
  resume_retention_days: 30,
  payg_per_resume_cost: 0.07,
  topup_min_amount: 1,
  topup_dodo_product_id: null,
};

export const usePlatformConfig = () => {
  return useQuery({
    queryKey: ["platform_config"],
    queryFn: async (): Promise<PlatformConfig> => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("max_resumes_per_job, max_file_size_mb, resume_retention_days, payg_per_resume_cost, topup_min_amount, topup_dodo_product_id")
        .limit(1)
        .single();
      if (error || !data) return DEFAULTS;
      return {
        ...data,
      };
    },
    retry: false,
    placeholderData: DEFAULTS,
  });
};

