import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { Save, Loader2 } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const ConfigTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);

  const { data: config } = useQuery({
    queryKey: ["admin_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
      if (error) throw error;
      return data;
    },
  });

  const [form, setForm] = useState({ max_resumes_per_job: 10, max_file_size_mb: 5, resume_retention_days: 30, payg_per_resume_cost: 0.07 });
  const [loaded, setLoaded] = useState(false);

  if (config && !loaded) {
    setForm({
      max_resumes_per_job: config.max_resumes_per_job,
      max_file_size_mb: config.max_file_size_mb,
      resume_retention_days: config.resume_retention_days,
      payg_per_resume_cost: (config as any).payg_per_resume_cost ?? 0.07,
    });
    setLoaded(true);
  }

  const validate = () => {
    if (form.max_resumes_per_job < 1) { toast.error("Max resumes per job must be at least 1"); return false; }
    if (form.max_file_size_mb < 1 || form.max_file_size_mb > 50) { toast.error("Max file size must be 1–50 MB"); return false; }
    if (form.resume_retention_days < 1) { toast.error("Retention days must be at least 1"); return false; }
    if (form.payg_per_resume_cost < 0) { toast.error("PAYG cost cannot be negative"); return false; }
    return true;
  };

  const save = async () => {
    if (!validate()) return;
    setSaving(true);
    try {
      const payload = { ...form } as any;
      const { error } = await supabase.from("platform_config").update(payload).eq("id", config?.id);
      if (error) { toast.error(error.message); return; }
      toast.success("Config updated");
      logAuditAction("config.update", "platform_config", config?.id, form);
      qc.invalidateQueries({ queryKey: ["admin_config"] });
      qc.invalidateQueries({ queryKey: ["platform_config"] });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card>
      <CardHeader className="pb-3"><CardTitle className="text-lg">Platform Configuration</CardTitle></CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div>
            <Label>Max Resumes/Job</Label>
            <Input type="number" min={1} value={form.max_resumes_per_job} onChange={(e) => setForm({ ...form, max_resumes_per_job: parseInt(e.target.value) || 0 })} />
          </div>
          <div>
            <Label>Max File Size (MB)</Label>
            <Input type="number" min={1} max={50} value={form.max_file_size_mb} onChange={(e) => setForm({ ...form, max_file_size_mb: parseInt(e.target.value) || 0 })} />
          </div>
          <div>
            <Label>Retention Days</Label>
            <Input type="number" min={1} value={form.resume_retention_days} onChange={(e) => setForm({ ...form, resume_retention_days: parseInt(e.target.value) || 0 })} />
          </div>
          <div>
            <Label>PAYG Per Resume Cost ($)</Label>
            <Input type="number" step="0.01" min={0} value={form.payg_per_resume_cost} onChange={(e) => setForm({ ...form, payg_per_resume_cost: parseFloat(e.target.value) || 0 })} />
          </div>
        </div>
        <Button onClick={save} disabled={saving}>
          {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
          Save Configuration
        </Button>
      </CardContent>
    </Card>
  );
};

export default ConfigTab;

