import AppHeader from "@/components/AppHeader";
import { CalendarCheck } from "lucide-react";

/**
 * To embed your booking widget, replace the placeholder below with your embed code.
 *
 * Examples:
 *   Calendly:  <iframe src="https://calendly.com/your-link" width="100%" height="700" frameBorder="0" />
 *   Cal.com:   <iframe src="https://cal.com/your-link" width="100%" height="700" frameBorder="0" />
 *   HubSpot:   Paste the HubSpot meetings embed snippet inside the embed container div.
 *
 * You can also set VITE_BOOKING_EMBED_URL in your .env to load an iframe dynamically.
 */

const BOOKING_EMBED_URL = import.meta.env.VITE_BOOKING_EMBED_URL as string | undefined;

const BookDemo = () => {
  return (
    <div className="min-h-screen bg-background">
      <AppHeader />
      <main className="mx-auto max-w-3xl px-4 py-8 space-y-6">
        <div className="flex items-center gap-3">
          <CalendarCheck className="h-6 w-6 text-primary" />
          <h1 className="text-2xl font-bold text-foreground">Book a Demo</h1>
        </div>
        <p className="text-muted-foreground">
          Schedule a personalized walkthrough of Rankora with our team.
        </p>

        {/* Booking embed container */}
        <div className="w-full min-h-[700px] rounded-lg border border-border bg-card overflow-hidden">
          {BOOKING_EMBED_URL ? (
            <iframe
              src={BOOKING_EMBED_URL}
              width="100%"
              height="700"
              frameBorder="0"
              title="Book a Demo"
              className="w-full"
              allow="camera; microphone"
            />
          ) : (
            <div className="flex flex-col items-center justify-center h-[700px] text-muted-foreground text-sm gap-2">
              <CalendarCheck className="h-10 w-10 text-muted-foreground/50" />
              <p>Booking widget will appear here.</p>
              <p className="text-xs">
                Set <code className="bg-muted px-1 py-0.5 rounded text-xs">VITE_BOOKING_EMBED_URL</code> or replace this placeholder with your embed code.
              </p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default BookDemo;

